function isNonEmptyString(value) {
    return typeof value === 'string' && value.trim().length > 0;
}
function hasItems(items) {
    return Array.isArray(items) && items.length > 0;
}
function argsContainPlannedTasks(args) {
    const tasks = args.tasks;
    if (!Array.isArray(tasks))
        return false;
    return tasks.some((task) => exports.plannedTaskArgSchema.safeParse(task).success);
}
function assertNever(value) {
    throw new Error(`Unhandled confirmation input type: ${String(value)}`);
}
function isDisplayableConfirmationRequest(payload) {
    if (hasItems(payload.setupRequests))
        return true;
    if (hasItems(payload.credentialRequests))
        return true;
    if (payload.domainAccess)
        return true;
    if (payload.channelConfig)
        return true;
    if (payload.mcpConnectRequest)
        return true;
    if (payload.testListener)
        return true;
    const inputType = payload.inputType ?? 'approval';
    switch (inputType) {
        case 'approval':
        case 'text':
        case 'continue':
            return isNonEmptyString(payload.message);
        case 'questions':
            return hasItems(payload.questions);
        case 'plan-review':
            return hasItems(payload.planItems) || argsContainPlannedTasks(payload.args);
        case 'resource-decision':
            return payload.resourceDecision !== undefined;
        default:
            return assertNever(inputType);
    }
}
