function getRenderHint(rawToolName) {
    const toolName = (0, builder_tool_names_1.resolveBuilderToolName)(rawToolName);
    if (toolName === builder_tool_names_1.WORKFLOW_BUILDER_TOOL_NAMES.TASK_CONTROL)
        return 'tasks';
    if (toolName === builder_tool_names_1.WORKFLOW_BUILDER_TOOL_NAMES.BUILD_WORKFLOW ||
        toolName === builder_tool_names_1.REMOVED_BUILDER_TOOL_NAMES.BUILD_WORKFLOW_WITH_AGENT)
        return 'builder';
    if (toolName === builder_tool_names_1.REMOVED_BUILDER_TOOL_NAMES.RESEARCH_WITH_AGENT)
        return 'researcher';
    if (toolName === builder_tool_names_1.WORKFLOW_BUILDER_TOOL_NAMES.CREATE_TASKS)
        return 'planner';
    if (toolName === builder_tool_names_1.REMOVED_BUILDER_TOOL_NAMES.EVAL_SETUP_WITH_AGENT)
        return 'eval-setup';
    if ([
        builder_tool_names_1.AGENT_BUILDER_TOOL_NAMES.CREATE_SKILLS,
        'list_skills',
        'read_skill',
        builder_tool_names_1.AGENT_BUILDER_TOOL_NAMES.UPDATE_SKILL,
        'load_skill',
    ].includes(toolName))
        return 'skill';
    return 'default';
}
